// ─────────────────────────────────────────────
// FLOATING PARTICLES
// ─────────────────────────────────────────────
const Particles = ({ isDark, count = 18 }) => {
  const [particles] = useState(() =>
    Array.from({ length: count }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      delay: Math.random() * 12,
      duration: 14 + Math.random() * 10,
      size: 1.5 + Math.random() * 2.5,
    }))
  );
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 0 }}>
      {particles.map(p => (
        <div key={p.id} style={{
          position: "absolute",
          bottom: "-10px",
          left: `${p.left}%`,
          width: `${p.size}px`,
          height: `${p.size}px`,
          borderRadius: "50%",
          background: isDark ? "rgba(232,185,122,0.6)" : "rgba(13,27,42,0.80)",
          animation: `drift ${p.duration}s ${p.delay}s linear infinite`,
          boxShadow: isDark ? `0 0 ${p.size * 3}px rgba(232,185,122,0.4)` : "none",
        }} />
      ))}
    </div>
  );
};

// ─────────────────────────────────────────────
// MOUSE-TRACKED ORB
// ─────────────────────────────────────────────
const TrackedOrb = ({ isDark }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  useEffect(() => {
    const move = (e) => {
      setPos({
        x: (e.clientX / window.innerWidth) * 100,
        y: (e.clientY / window.innerHeight) * 100,
      });
    };
    window.addEventListener("mousemove", move, { passive: true });
    return () => window.removeEventListener("mousemove", move);
  }, []);
  return (
    <div style={{
      position: "fixed",
      left: `${pos.x}%`,
      top: `${pos.y}%`,
      transform: "translate(-50%,-50%)",
      width: "600px",
      height: "600px",
      borderRadius: "50%",
      background: isDark
        ? "radial-gradient(circle, rgba(196,132,90,0.07) 0%, transparent 65%)"
        : "radial-gradient(circle, rgba(160,98,60,0.06) 0%, transparent 65%)",
      pointerEvents: "none",
      transition: "left 1.2s cubic-bezier(0.25,0.46,0.45,0.94), top 1.2s cubic-bezier(0.25,0.46,0.45,0.94)",
      zIndex: 0,
    }} />
  );
};

