// ─────────────────────────────────────────────
// CHAT TAB
// ─────────────────────────────────────────────
const ChatTab = ({ isDark }) => {
  const t = isDark ? tokens.dark : tokens.light;
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [greetingLoading, setGreetingLoading] = useState(true);
  const [inputFocused, setInputFocused] = useState(false);
  const bottomRef = useRef(null);


  useEffect(() => {
    const fetchGreeting = async () => {
      try {
        const res = await fetch("/api/greeting", { method: "POST" });
        const data = await res.json();
        setMessages([{ role: "assistant", text: data.response }]);
      } catch {
        setMessages([{
          role: "assistant",
          text: "Assalam-o-Alaikum\n\nI am Sakina — a space for stillness. What's on your mind?",
        }]);
      } finally {
        setGreetingLoading(false);
      }
    };
    fetchGreeting();
  }, []);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, loading]);



  const sendMessage = async () => {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setMessages(prev => [...prev, { role: "user", text }]);
    setLoading(true);
    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: text }),
      });
      const data = await res.json();
      setMessages(prev => [...prev, { role: "assistant", text: data.response }]);
    } catch {
      setMessages(prev => [...prev, { role: "assistant", text: "I'm here — there seems to be a connection issue. Please try again." }]);
    } finally {
      setLoading(false);
    }
  };

  const handleKey = (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", position: "relative" }}>
      {/* Subtle bg glow behind chat */}
      <div style={{
        position: "absolute",
        top: "30%",
        left: "50%",
        transform: "translate(-50%,-50%)",
        width: "500px",
        height: "500px",
        borderRadius: "50%",
        background: isDark
          ? "radial-gradient(circle, rgba(196,132,90,0.04) 0%, transparent 65%)"
          : "radial-gradient(circle, rgba(160,98,60,0.04) 0%, transparent 65%)",
        pointerEvents: "none",
        zIndex: 0,
      }} />

      {/* Messages */}
      <div style={{
        flex: 1,
        overflowY: "auto",
        padding: "2rem 1.8rem 1rem",
        display: "flex",
        flexDirection: "column",
        gap: "1.2rem",
        position: "relative",
        zIndex: 1,
      }}>
        {greetingLoading && messages.length === 0 && (
          <div style={{ display: "flex", justifyContent: "flex-start", alignItems: "center", gap: "8px" }}>
            <div style={{
              width: "28px", height: "28px", borderRadius: "50%",
              background: `linear-gradient(135deg, ${t.glow}, ${t.goldSoft})`,
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "11px", flexShrink: 0,
              boxShadow: `0 0 12px rgba(196,132,90,0.3)`,
            }}>✦</div>
            <div style={{
              padding: "13px 17px",
              borderRadius: "18px 18px 18px 4px",
              background: t.aiBubble,
              border: `1px solid ${t.border}`,
              color: t.textSecond,
              fontSize: "0.85rem",
            }}>
              Listening...
            </div>
          </div>
        )}
        {messages.map((msg, i) => (
          <div key={i} style={{
            display: "flex",
            justifyContent: msg.role === "user" ? "flex-end" : "flex-start",
            animation: "fadeUp 0.45s ease forwards",
          }}>
            {/* Avatar for assistant */}
            {msg.role === "assistant" && (
              <div style={{
                width: "28px",
                height: "28px",
                borderRadius: "50%",
                background: `linear-gradient(135deg, ${t.glow}, ${t.goldSoft})`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "11px",
                marginRight: "8px",
                flexShrink: 0,
                marginTop: "4px",
                boxShadow: `0 0 12px rgba(196,132,90,0.3)`,
                animation: "pulse-ring 3s ease-in-out infinite",
              }}>
                ✦
              </div>
            )}
            <div style={{
              maxWidth: "75%",
              padding: "13px 17px",
              borderRadius: msg.role === "user" ? "18px 18px 4px 18px" : "18px 18px 18px 4px",
              background: msg.role === "user" ? t.userBubble : t.aiBubble,
              backdropFilter: "blur(16px)",
              WebkitBackdropFilter: "blur(16px)",
              border: `1px solid ${t.border}`,
              boxShadow: t.shadow + ", inset 0 1px 0 " + t.innerLight,
              fontSize: "0.88rem",
              lineHeight: 1.75,
              color: t.textPrimary,
              whiteSpace: "pre-wrap",
              fontWeight: 300,
            }}>
              {msg.text}
            </div>
          </div>
        ))}

        {loading && (
          <div style={{ display: "flex", justifyContent: "flex-start", alignItems: "center", gap: "8px" }}>
            <div style={{
              width: "28px", height: "28px", borderRadius: "50%",
              background: `linear-gradient(135deg, ${t.glow}, ${t.goldSoft})`,
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "11px", flexShrink: 0,
              boxShadow: `0 0 12px rgba(196,132,90,0.3)`,
            }}>✦</div>
            <div style={{
              padding: "13px 17px",
              borderRadius: "18px 18px 18px 4px",
              background: t.aiBubble,
              backdropFilter: "blur(16px)",
              WebkitBackdropFilter: "blur(16px)",
              border: `1px solid ${t.border}`,
              boxShadow: t.shadow,
            }}>
              <TypingIndicator t={t} />
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      {/* Input area */}
      <div style={{
        padding: "1rem 1.8rem 1.6rem",
        borderTop: `1px solid ${t.border}`,
        display: "flex",
        gap: "10px",
        alignItems: "flex-end",
        background: t.glass,
        backdropFilter: "blur(20px)",
        WebkitBackdropFilter: "blur(20px)",
        position: "relative",
        zIndex: 1,
      }}>
        <div style={{
          flex: 1,
          position: "relative",
          borderRadius: "14px",
          background: inputFocused
            ? `linear-gradient(${t.glassCard}, ${t.glassCard}) padding-box, linear-gradient(135deg, ${t.glow}, ${t.goldSoft}, ${t.glow}) border-box`
            : undefined,
          border: inputFocused ? "1px solid transparent" : `1px solid ${t.border}`,
          transition: "all 0.3s ease",
          boxShadow: inputFocused ? `0 0 20px rgba(196,132,90,0.12)` : "none",
        }}>
          <textarea
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={handleKey}
            onFocus={() => setInputFocused(true)}
            onBlur={() => setInputFocused(false)}
            placeholder="Share what's on your heart…"
            rows={1}
            style={{
              width: "100%",
              background: t.glassCard,
              backdropFilter: "blur(16px)",
              border: "none",
              borderRadius: "14px",
              padding: "13px 17px",
              color: t.textPrimary,
              fontSize: "0.88rem",
              fontFamily: "'Inter', sans-serif",
              resize: "none",
              outline: "none",
              lineHeight: 1.65,
              fontWeight: 300,
              maxHeight: "130px",
              overflowY: "auto",
            }}
          />
        </div>
        <button
          onClick={sendMessage}
          disabled={loading || !input.trim()}
          style={{
            background: input.trim() && !loading
              ? `linear-gradient(135deg, ${t.glow}, ${t.goldSoft})`
              : t.border,
            border: "none",
            borderRadius: "12px",
            width: "44px",
            height: "44px",
            cursor: input.trim() && !loading ? "pointer" : "default",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transition: "all 0.25s ease",
            flexShrink: 0,
            boxShadow: input.trim() && !loading ? `0 4px 16px rgba(196,132,90,0.35)` : "none",
            transform: input.trim() && !loading ? "scale(1)" : "scale(0.96)",
          }}
          onMouseEnter={e => { if (input.trim() && !loading) e.currentTarget.style.transform = "scale(1.05)"; }}
          onMouseLeave={e => { e.currentTarget.style.transform = "scale(1)"; }}
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
            stroke={isDark ? tokens.dark.bgBase : "#fff"}
            strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <line x1="22" y1="2" x2="11" y2="13" />
            <polygon points="22 2 15 22 11 13 2 9 22 2" />
          </svg>
        </button>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// DHIKR TAB
// ─────────────────────────────────────────────
const EMOTIONS = ["anxiety", "grief", "panic", "overwhelmed", "loneliness", "guilt", "restlessness", "hopelessness", "gratitude", "calm", "contentment", "hope"];

const DhikrTab = ({ isDark }) => {
  const t = isDark ? tokens.dark : tokens.light;
  const [mode, setMode] = useState("islamic");
  const [emotion, setEmotion] = useState("");
  const [freeText, setFreeText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState("mode");

  const labelStyle = {
    fontSize: "0.68rem",
    letterSpacing: "0.14em",
    textTransform: "uppercase",
    color: t.textMuted,
    marginBottom: "1.2rem",
    display: "block",
  };

  const handleModeSelect = (m) => { setMode(m); setStep("emotion"); };

  const handleEmotionSelect = async (e) => {
    const selected = e || emotion;
    if (!selected) return;
    setEmotion(selected);
    setLoading(true);
    setStep("result");
    try {
      const res = await fetch("/api/dhikr", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ emotion: selected, mode, free_text: freeText }),
      });
      const data = await res.json();
      setResult(data);
    } catch { setResult({ error: true }); }
    finally { setLoading(false); }
  };

  const reset = () => { setStep("mode"); setEmotion(""); setFreeText(""); setResult(null); };

  if (step === "mode") return (
    <div style={{ padding: "2.5rem 2rem", animation: "fadeUp 0.5s ease forwards" }}>
      <span style={labelStyle}>How would you like guidance today?</span>
      <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap" }}>
        {[
          { key: "islamic", label: "Dhikr & Du'a", sub: "Islamic spiritual practices", icon: "☽" },
          { key: "secular", label: "Evidence-Based", sub: "Scientifically grounded practices", icon: "◎" },
        ].map(opt => (
          <button key={opt.key} onClick={() => handleModeSelect(opt.key)}
            className="glass-card"
            style={{
              flex: "1 1 180px",
              borderRadius: "12px",
              padding: "1.6rem 1.4rem",
              cursor: "pointer",
              textAlign: "left",
              color: t.textPrimary,
            }}
            onMouseEnter={e => e.currentTarget.style.borderColor = t.borderGlow}
            onMouseLeave={e => e.currentTarget.style.borderColor = t.border}
          >
            <div style={{ fontSize: "1.4rem", marginBottom: "0.7rem", color: t.gold }}>{opt.icon}</div>
            <div style={{ fontSize: "0.95rem", fontWeight: 500, marginBottom: "0.35rem", color: t.gold }}>{opt.label}</div>
            <div style={{ fontSize: "0.78rem", color: t.textMuted, fontWeight: 300 }}>{opt.sub}</div>
          </button>
        ))}
      </div>
    </div>
  );

  if (step === "emotion") return (
    <div style={{ padding: "2.5rem 2rem", animation: "fadeUp 0.5s ease forwards" }}>
      <span style={labelStyle}>What are you feeling right now?</span>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "0.6rem", marginBottom: "1.8rem" }}>
        {EMOTIONS.map(em => (
          <button key={em} onClick={() => handleEmotionSelect(em)} style={{
            background: t.glass,
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            border: `1px solid ${t.border}`,
            borderRadius: "22px",
            padding: "9px 20px",
            cursor: "pointer",
            color: t.textSecond,
            fontSize: "0.82rem",
            transition: "all 0.22s ease",
            textTransform: "capitalize",
            boxShadow: t.shadow,
          }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = t.borderGlow; e.currentTarget.style.color = t.glow; e.currentTarget.style.boxShadow = t.shadowGlow; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = t.border; e.currentTarget.style.color = t.textSecond; e.currentTarget.style.boxShadow = t.shadow; }}
          >{em}</button>
        ))}
      </div>
      <div style={{ borderTop: `1px solid ${t.border}`, paddingTop: "1.4rem" }}>
        <span style={{ ...labelStyle, marginBottom: "0.7rem" }}>Or describe it in your own words</span>
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            value={freeText}
            onChange={e => setFreeText(e.target.value)}
            onKeyDown={e => e.key === "Enter" && freeText.trim() && handleEmotionSelect(freeText)}
            placeholder="e.g. I feel like everything is too much…"
            style={{
              flex: 1,
              background: t.glassCard,
              backdropFilter: "blur(16px)",
              border: `1px solid ${t.border}`,
              borderRadius: "10px",
              padding: "11px 16px",
              color: t.textPrimary,
              fontSize: "0.85rem",
              fontFamily: "'Inter', sans-serif",
              outline: "none",
              fontWeight: 300,
              transition: "border-color 0.2s",
            }}
            onFocus={e => e.target.style.borderColor = t.borderGlow}
            onBlur={e => e.target.style.borderColor = t.border}
          />
          <button onClick={() => freeText.trim() && handleEmotionSelect(freeText)} style={{
            background: `linear-gradient(135deg, ${t.glow}, ${t.goldSoft})`,
            border: "none",
            borderRadius: "10px",
            padding: "11px 20px",
            cursor: "pointer",
            color: isDark ? tokens.dark.bgBase : "#fff",
            fontSize: "0.82rem",
            boxShadow: `0 4px 16px rgba(196,132,90,0.3)`,
            transition: "transform 0.2s ease",
          }}
            onMouseEnter={e => e.currentTarget.style.transform = "scale(1.04)"}
            onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}
          >→</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ padding: "2rem 2rem 2.5rem", overflowY: "auto", height: "100%", animation: "fadeUp 0.5s ease forwards" }}>
      {loading ? (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "200px", gap: "1.2rem" }}>
          <SakinaLogo size={44} color={isDark ? tokens.dark.gold : tokens.light.gold} style={{ opacity: 0.6, animation: "breathe 2s ease-in-out infinite" }} />
          <span style={{ fontSize: "0.78rem", color: t.textMuted, letterSpacing: "0.1em" }}>Reflecting…</span>
        </div>
      ) : result?.error ? (
        <div style={{ color: t.textMuted, fontSize: "0.88rem" }}>Something went wrong. Please try again.</div>
      ) : result && (
        <>
          <div style={{ marginBottom: "2rem" }}>
            <span style={labelStyle}>{emotion.charAt(0).toUpperCase() + emotion.slice(1)}</span>
            <p style={{ fontSize: "0.9rem", lineHeight: 1.85, color: t.textSecond, fontWeight: 300 }}>{result.commentary}</p>
          </div>
          {result.practices?.map((p, i) => (
            <div key={i} className="glass-card" style={{ borderRadius: "12px", padding: "1.6rem", marginBottom: "1rem" }}>
              {mode === "islamic" ? (
                <>
                  <div className="arabic" style={{ fontSize: "1.5rem", color: t.gold, marginBottom: "0.7rem", lineHeight: 2 }}>{p.arabic}</div>
                  <div style={{ fontSize: "0.85rem", color: t.goldSoft, marginBottom: "0.5rem", fontStyle: "italic" }}>{p.transliteration}</div>
                  <div style={{ fontSize: "0.88rem", color: t.textPrimary, marginBottom: "1rem", fontWeight: 300 }}>"{p.translation}"</div>
                  <div style={{ fontSize: "0.75rem", color: t.textMuted, marginBottom: "0.3rem" }}>📖 {p.reference}</div>
                  <div style={{ fontSize: "0.75rem", color: t.textMuted, marginBottom: p.personalization ? "0" : undefined }}>🔁 {p.repetitions}</div>
                </>
              ) : (
                <>
                  <div style={{ fontSize: "0.96rem", color: t.gold, fontWeight: 500, marginBottom: "0.7rem" }}>{p.name}</div>
                  <div style={{ fontSize: "0.88rem", color: t.textPrimary, marginBottom: "0.9rem", fontWeight: 300, lineHeight: 1.75 }}>{p.instruction}</div>
                  <div style={{ fontSize: "0.8rem", color: t.textSecond, marginBottom: "0.5rem", lineHeight: 1.65 }}>Why it works: {p.why}</div>
                  <div style={{ fontSize: "0.75rem", color: t.textMuted, marginBottom: p.personalization ? "0" : undefined }}>📚 {p.source}</div>
                </>
              )}
              {p.personalization && (
                <div style={{
                  marginTop: "1rem",
                  paddingTop: "0.9rem",
                  borderTop: `1px solid ${t.border}`,
                  fontSize: "0.82rem",
                  color: t.textSecond,
                  lineHeight: 1.75,
                  fontStyle: "italic",
                  fontWeight: 300,
                }}>
                  ✦ {p.personalization}
                </div>
              )}
            </div>
          ))}
          <button onClick={reset} style={{
            marginTop: "0.5rem",
            background: t.glass,
            backdropFilter: "blur(12px)",
            border: `1px solid ${t.border}`,
            borderRadius: "8px",
            padding: "11px 22px",
            cursor: "pointer",
            color: t.textMuted,
            fontSize: "0.78rem",
            letterSpacing: "0.08em",
            transition: "all 0.22s ease",
          }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = t.borderGlow; e.currentTarget.style.color = t.glow; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = t.border; e.currentTarget.style.color = t.textMuted; }}
          >← Start over</button>
        </>
      )}
    </div>
  );
};

// ─────────────────────────────────────────────
// APP PAGE
// ─────────────────────────────────────────────
const AppPage = ({ isDark, onToggleTheme }) => {
  const t = isDark ? tokens.dark : tokens.light;
  const [tab, setTab] = useState("chat");
  const navItems = [
    { key: "chat", label: "Chat", icon: "◎" },
    { key: "dhikr", label: "Dhikr", icon: "✦" },
    { key: "mood", label: "Mood Tracker", icon: "❀" },
  ];

  return (
    <div style={{ height: "100vh", display: "flex", position: "relative", overflow: "hidden" }}>
      <MeshBackground isDark={isDark} />
      <TrackedOrb isDark={isDark} />

      {/* Sidebar */}
      <div className="glass-panel" style={{
        width: "210px",
        flexShrink: 0,
        display: "flex",
        flexDirection: "column",
        padding: "2rem 1.3rem",
        gap: "0.3rem",
        zIndex: 10,
        borderRight: `1px solid ${t.border}`,
        borderTop: "none",
        borderBottom: "none",
        borderLeft: "none",
        borderRadius: 0,
      }}>
        {/* Logo in sidebar */}
        <div style={{ marginBottom: "2rem", paddingLeft: "0.3rem" }}>
          <SakinaLogo size={52} color={t.gold} style={{ marginBottom: "4px" }} />
          <div className="display" style={{
            fontSize: "1.25rem",
            fontWeight: 400,
            color: t.textPrimary,
            letterSpacing: "0.12em",
            marginTop: "4px",
          }}>Sakina</div>
        </div>

        {navItems.map(item => (
          <button key={item.key} onClick={() => setTab(item.key)} style={{
            background: tab === item.key ? `${t.glow}16` : "transparent",
            backdropFilter: tab === item.key ? "blur(10px)" : "none",
            border: `1px solid ${tab === item.key ? t.borderGlow : "transparent"}`,
            borderRadius: "10px",
            padding: "11px 14px",
            cursor: "pointer",
            color: tab === item.key ? t.glow : t.textMuted,
            fontSize: "0.83rem",
            fontFamily: "'Inter', sans-serif",
            textAlign: "left",
            transition: "all 0.22s ease",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            letterSpacing: "0.04em",
            boxShadow: tab === item.key ? `0 0 14px rgba(196,132,90,0.08)` : "none",
          }}
            onMouseEnter={e => { if (tab !== item.key) { e.currentTarget.style.color = t.textSecond; e.currentTarget.style.background = `${t.glow}08`; } }}
            onMouseLeave={e => { if (tab !== item.key) { e.currentTarget.style.color = t.textMuted; e.currentTarget.style.background = "transparent"; } }}
          >
            <span style={{ fontSize: "0.68rem" }}>{item.icon}</span>
            {item.label}
          </button>
        ))}

        <div style={{ flex: 1 }} />
        <ThemeToggle isDark={isDark} onToggle={onToggleTheme} />
      </div>

      {/* Main content area */}
      <div style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        position: "relative",
        zIndex: 5,
      }}>
        {/* Tab header */}
        <div style={{
          padding: "1.1rem 1.8rem",
          borderBottom: `1px solid ${t.border}`,
          display: "flex",
          alignItems: "center",
          gap: "0.7rem",
          background: t.glass,
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          boxShadow: `inset 0 -1px 0 ${t.border}`,
        }}>
          <span style={{ fontSize: "0.65rem", color: t.glow }}>{navItems.find(n => n.key === tab)?.icon}</span>
          <span style={{ fontSize: "0.72rem", letterSpacing: "0.12em", textTransform: "uppercase", color: t.textMuted }}>
            {navItems.find(n => n.key === tab)?.label}
          </span>
        </div>

        <div style={{ flex: 1, overflow: "hidden", display: "flex", flexDirection: "column" }}>
          {tab === "chat" && <ChatTab isDark={isDark} />}
          {tab === "dhikr" && <DhikrTab isDark={isDark} />}
          {tab === "mood" && <MoodTab isDark={isDark} tokensRef={tokens} />}
        </div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// ROOT
// ─────────────────────────────────────────────
export default function App() {
  const [isDark, setIsDark] = useState(true);
  const [page, setPage] = useState("landing");
  return (
    <>
      <GlobalStyles isDark={isDark} />
      {page === "landing"
        ? <LandingPage isDark={isDark} onEnter={() => setPage("app")} onToggleTheme={() => setIsDark(d => !d)} />
        : <AppPage isDark={isDark} onToggleTheme={() => setIsDark(d => !d)} />
      }
    </>
  );
}